export type AccountingPostingRequest={version:1;actor:string;tenant:string;property:string;request:string;kind:'service'|'forward';reservation:string;serviceDate:string;adjustment:string|null;mapping:string;mappingVersion:number;period:string;postingDate:string;noLines:boolean};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v);
const date=(v:unknown):v is string=>{if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const t=Date.parse(v+'T00:00:00Z');return Number.isFinite(t)&&new Date(t).toISOString().slice(0,10)===v;};
export function validateAccountingRequest(value:unknown):AccountingPostingRequest{
 if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Saved accounting request cannot be read.');const v=value as AccountingPostingRequest;
 if(Object.keys(v).sort().join(',')!=='actor,adjustment,kind,mapping,mappingVersion,noLines,period,postingDate,property,request,reservation,serviceDate,tenant,version'||v.version!==1||![v.actor,v.tenant,v.property,v.request,v.reservation,v.mapping,v.period].every(uuid)||!['service','forward'].includes(v.kind)||(v.kind==='forward'?!uuid(v.adjustment):v.adjustment!==null)||!date(v.serviceDate)||!date(v.postingDate)||v.postingDate<v.serviceDate||!Number.isSafeInteger(v.mappingVersion)||v.mappingVersion<1||typeof v.noLines!=='boolean')throw Error('Saved accounting request is invalid; reconcile it before starting another posting.');return v;
}
export function accountingRequestKey(actor:string,tenant:string,property:string){if(![actor,tenant,property].every(uuid))throw Error('Verified accounting scope required.');return 'iratepilot-pms-accounting:'+actor+':'+tenant+':'+property;}
export function accountingRequestParams(request:AccountingPostingRequest){const v=validateAccountingRequest(request);return {p_tenant:v.tenant,p_property:v.property,p_request:v.request,p_mapping:v.mapping,p_period:v.period,p_posting_date:v.postingDate,p_confirmed:true,...(v.kind==='forward'?{p_adjustment:v.adjustment}:{p_service_date:v.serviceDate,p_reservation:v.reservation})};}
export function retainAccountingRequest(storage:Pick<Storage,'getItem'|'setItem'>,request:AccountingPostingRequest){const v=validateAccountingRequest(request),key=accountingRequestKey(v.actor,v.tenant,v.property),text=JSON.stringify(v),prior=storage.getItem(key);if(prior!==null&&prior!==text)throw Error('An accounting request is already pending. Check its result first.');storage.setItem(key,text);if(storage.getItem(key)!==text)throw Error('Accounting request could not be retained.');}
export function readAccountingRequest(storage:Pick<Storage,'getItem'>,actor:string,tenant:string,property:string){const raw=storage.getItem(accountingRequestKey(actor,tenant,property));if(raw===null)return null;const v=validateAccountingRequest(JSON.parse(raw));if(v.actor!==actor||v.tenant!==tenant||v.property!==property)throw Error('Saved accounting request belongs to another scope.');return v;}
export function accountingReceiptMatches(value:unknown,request:AccountingPostingRequest):boolean{
 const r=validateAccountingRequest(request);if(!value||typeof value!=='object')return false;const v=value as Record<string,unknown>;
 return v.schema_version===1&&v.tenant_id===r.tenant&&v.property_id===r.property&&v.request_id===r.request&&v.reservation_id===r.reservation&&v.service_date===r.serviceDate&&v.mapping_id===r.mapping&&v.mapping_version===r.mappingVersion&&v.posting_date===r.postingDate&&typeof v.replayed==='boolean'&&(r.kind==='forward'?v.adjustment_id===r.adjustment&&v.no_posting_lines===r.noLines:v.zero_amount===r.noLines)&&(r.noLines?v.journal_id===null:uuid(v.journal_id));
}
export function clearAccountingRequest(storage:Pick<Storage,'getItem'|'removeItem'>,request:AccountingPostingRequest,receipt:unknown){if(!accountingReceiptMatches(receipt,request))throw Error('Posting receipt does not match the saved request.');const key=accountingRequestKey(request.actor,request.tenant,request.property);if(storage.getItem(key)!==JSON.stringify(request))throw Error('Saved accounting request changed; refresh recovery.');storage.removeItem(key);if(storage.getItem(key)!==null)throw Error('Saved accounting request could not be cleared.');}
export function readAccountingStatus(value:unknown,request:AccountingPostingRequest):{found:false}|{found:true;receipt:Record<string,unknown>}{
 const r=validateAccountingRequest(request);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Accounting recovery response is unavailable.');const v=value as Record<string,unknown>;
 if(v.schema_version!==1||v.actor_id!==r.actor||v.tenant_id!==r.tenant||v.property_id!==r.property||v.request_id!==r.request||v.action!==(r.kind==='forward'?'post_forward_journal':'post_service_journal')||typeof v.found!=='boolean')throw Error('Accounting recovery response belongs to another request.');
 if(!v.found){if(v.result!==null||v.command!==null)throw Error('Invalid missing-request response.');return {found:false};}
 const command=r.kind==='forward'?{adjustment_id:r.adjustment,mapping_id:r.mapping,period_id:r.period,posting_date:r.postingDate}:{service_date:r.serviceDate,reservation_id:r.reservation,mapping_id:r.mapping,period_id:r.period,posting_date:r.postingDate};
 if(!v.command||typeof v.command!=='object'||Array.isArray(v.command)||Object.keys(v.command).sort().join(',')!==Object.keys(command).sort().join(',')||!Object.entries(command).every(([k,x])=>(v.command as Record<string,unknown>)[k]===x)||!accountingReceiptMatches(v.result,r))throw Error('Saved posting does not match the retained command.');
 return {found:true,receipt:v.result as Record<string,unknown>};
}
export function accountingRetirementParams(r:AccountingPostingRequest){validateAccountingRequest(r);return {p_tenant:r.tenant,p_property:r.property,p_request:r.request,p_kind:r.kind,p_confirmed:true,p_command:r.kind==='forward'?{adjustment_id:r.adjustment,mapping_id:r.mapping,period_id:r.period,posting_date:r.postingDate}:{service_date:r.serviceDate,reservation_id:r.reservation,mapping_id:r.mapping,period_id:r.period,posting_date:r.postingDate}};}
export function readAccountingRetirement(value:unknown,r:AccountingPostingRequest):boolean{
 validateAccountingRequest(r);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Posting cancellation result unavailable.');const v=value as Record<string,unknown>;
 if(v.schema_version!==1||v.actor_id!==r.actor||v.tenant_id!==r.tenant||v.property_id!==r.property||v.request_id!==r.request||v.kind!==r.kind||typeof v.retired!=='boolean'||typeof v.replayed!=='boolean')throw Error('Posting cancellation belongs to another request.');
 if(!v.retired){if(v.command!==null||v.retired_at!==null)throw Error('Invalid missing cancellation response.');return false;}
 const command=accountingRetirementParams(r).p_command;
 if(!v.command||typeof v.command!=='object'||Array.isArray(v.command)||Object.keys(v.command).sort().join(',')!==Object.keys(command).sort().join(',')||!Object.entries(command).every(([k,x])=>(v.command as Record<string,unknown>)[k]===x)||typeof v.retired_at!=='string'||!Number.isFinite(Date.parse(v.retired_at)))throw Error('Posting cancellation does not match the retained command.');return true;
}
export function clearAccountingRetirement(storage:Pick<Storage,'getItem'|'removeItem'>,r:AccountingPostingRequest,value:unknown){if(!readAccountingRetirement(value,r))throw Error('Posting cancellation is not saved.');const key=accountingRequestKey(r.actor,r.tenant,r.property);if(storage.getItem(key)!==JSON.stringify(r))throw Error('Retained posting changed. Reopen recovery.');storage.removeItem(key);if(storage.getItem(key)!==null)throw Error('Cancelled posting request could not be cleared.');}
